// 热门提示词按「收藏数 + 评论数」降序取前若干条，再以 ID 升序保证取值确定。
func (q *Queries) AdminHotPrompts(ctx context.Context, limitCount int32) ([]AdminHotPromptsRow, error) {
	rows, err := q.db.Query(ctx, adminHotPrompts, limitCount)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []AdminHotPromptsRow{}
	for rows.Next() {
		var i AdminHotPromptsRow
		if err := rows.Scan(
			&i.ID,
			&i.Title,
			&i.Visibility,
			&i.CommentCount,
			&i.FavoriteCount,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

